import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"任务覆盖与完成定义","description":"Hearth 的八类任务覆盖、A0–A3 自主级别与不同任务类型的完成证据。","frontmatter":{"title":"任务覆盖与完成定义","description":"Hearth 的八类任务覆盖、A0–A3 自主级别与不同任务类型的完成证据。","outline":[2,3]},"headers":[],"relativePath":"product/task-coverage.md","filePath":"product/task-coverage.md","lastUpdated":null}'),o={name:"product/task-coverage.md"};function h(n,t,s,i,l,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<p class="eyebrow">TASK COVERAGE &amp; DONE</p><h1 id="任务覆盖与完成定义" tabindex="-1">任务覆盖与完成定义 <a class="header-anchor" href="#任务覆盖与完成定义" aria-label="Permalink to &quot;任务覆盖与完成定义&quot;">​</a></h1><p class="lead">Hearth 不追求“什么都能做”，而是用明确的八类任务、自主级别和验证器定义什么值得做、什么时候可以自动做、什么才算完成。</p><h2 id="八类任务覆盖" tabindex="-1">八类任务覆盖 <a class="header-anchor" href="#八类任务覆盖" aria-label="Permalink to &quot;八类任务覆盖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务族</th><th>典型工作</th><th>首选执行方式</th></tr></thead><tbody><tr><td>沟通与协作</td><td>邮件、IM、会议纪要、跟进、日程协调</td><td>Connector + Native/Codex + 审批</td></tr><tr><td>文档与内容</td><td>docx、xlsx、pptx、PDF、Markdown、报告、翻译、改写</td><td>Document/Data Engine、Native、Codex</td></tr><tr><td>研究与信息整理</td><td>搜索、阅读、对比、引用、摘要、资料库</td><td>Native + Browser + Codex</td></tr><tr><td>代码与研发</td><td>仓库修改、测试、Issue、PR、代码审查</td><td>Codex + 测试/CI 工具</td></tr><tr><td>数据与表格</td><td>清洗、对账、统计、图表、导入导出</td><td>Document/Data Engine + Python sidecar</td></tr><tr><td>网页与 SaaS</td><td>登录、表单、下载、上传、后台操作</td><td>Browser Executor</td></tr><tr><td>桌面应用</td><td>没有 API 的软件、系统设置、跨应用流程</td><td>GUI Executor</td></tr><tr><td>个人事务</td><td>表单、预约、账单、提醒、设备操作</td><td>Connector、Browser、GUI，高风险审批</td></tr></tbody></table><p>一个任务可由多个执行器协作；“调研竞品并写进周报”可能同时使用 Browser、Native、Document Engine 和 Codex。</p><h2 id="自主级别" tabindex="-1">自主级别 <a class="header-anchor" href="#自主级别" aria-label="Permalink to &quot;自主级别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>行为</th><th>默认使用</th></tr></thead><tbody><tr><td>A0 建议</td><td>只生成建议、草稿或计划</td><td>新场景、高风险、未验证能力</td></tr><tr><td>A1 受控执行</td><td>自动完成低风险步骤，中风险首次审批</td><td>Stage 1–2 默认</td></tr><tr><td>A2 授权执行</td><td>在 Mandate 内自动完成已授权动作，高风险仍需审批</td><td>Stage 4 以后</td></tr><tr><td>A3 受监督自主</td><td>长周期运行，但保留审批、预算、kill switch 和回执</td><td>长期目标</td></tr></tbody></table><p>自主性必须按任务族、来源、时间段、设备、风险和金额独立配置，不能用一个“全自动开关”覆盖所有场景。</p><h2 id="完成-的定义" tabindex="-1">“完成”的定义 <a class="header-anchor" href="#完成-的定义" aria-label="Permalink to &quot;“完成”的定义&quot;">​</a></h2><p>自然语言“已完成”不是完成证据。不同任务需要不同验证器：</p><table tabindex="0"><thead><tr><th>任务</th><th>完成证据</th></tr></thead><tbody><tr><td>代码/Issue/PR</td><td>测试、类型检查、diff、CI 或人工审查</td></tr><tr><td>文档</td><td>结构检查、引用检查、格式检查、用户验收</td></tr><tr><td>邮件草稿</td><td>收件人、事实、语气检查；发送前审批</td></tr><tr><td>邮件发送</td><td>Approval、Broker 执行记录、provider message id 或明确的不确定状态</td></tr><tr><td>网页操作</td><td>DOM/可访问性状态、截图、最终状态和回执</td></tr><tr><td>桌面操作</td><td>可访问性树、截图、目标状态和人工确认</td></tr><tr><td>研究</td><td>来源可追溯，关键断言有引用</td></tr><tr><td>日程</td><td>时间、时区、参与者、冲突检查和日历回执</td></tr><tr><td>数据</td><td>schema、行数、抽样、对账和可复现脚本</td></tr></tbody></table>',12)])])}const b=d(o,[["render",h]]);export{u as __pageData,b as default};
